function trieOps(ops) {
  const root = { children: new Map(), end: false }
  // Follow the letters from the root; return the last node, or null if a letter is missing.
  const walk = (text) => {
    let node = root
    for (const ch of text) {
      node = node.children.get(ch)
      if (!node) return null
    }
    return node
  }
  const out = []
  for (const [op, word] of ops) {
    if (op === 'insert') {
      let node = root
      for (const ch of word) {
        if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), end: false })
        node = node.children.get(ch)
      }
      node.end = true
    } else if (op === 'search') {
      const node = walk(word)
      out.push(node !== null && node.end)
    } else {
      out.push(walk(word) !== null)
    }
  }
  return out
}

