class TrieNode:
    def __init__(self):
        self.children = {}   # letter -> TrieNode
        self.end = False     # True if a word ends at this node


def trie_ops(ops):
    root = TrieNode()

    def walk(text):
        # Follow the letters from the root; return the last node, or None if a letter is missing.
        node = root
        for ch in text:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    out = []
    for op, word in ops:
        if op == "insert":
            node = root
            for ch in word:
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
            node.end = True
        elif op == "search":
            node = walk(word)
            out.append(node is not None and node.end)
        else:
            out.append(walk(word) is not None)
    return out

