function autocomplete(words, typed) {
  const root = { children: new Map(), top: [] }
  // Sorted order means the first three words to pass a node are its three smallest matches.
  for (const word of [...words].sort()) {
    let node = root
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), top: [] })
      node = node.children.get(ch)
      if (node.top.length < 3) node.top.push(word)
    }
  }
  const out = []
  let node = root
  for (const ch of typed) {
    node = node ? node.children.get(ch) : undefined
    out.push(node ? [...node.top] : [])
  }
  return out
}

