function wordDictionaryOps(ops) {
  const root = { children: new Map(), end: false }
  // Does the rest of the pattern, from index i, match a word below node?
  const matches = (node, pattern, i) => {
    if (i === pattern.length) return node.end
    const ch = pattern[i]
    if (ch === '.') {
      for (const child of node.children.values()) {
        if (matches(child, pattern, i + 1)) return true
      }
      return false
    }
    const child = node.children.get(ch)
    return child !== undefined && matches(child, pattern, i + 1)
  }
  const out = []
  for (const [op, text] of ops) {
    if (op === 'add') {
      let node = root
      for (const ch of text) {
        if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), end: false })
        node = node.children.get(ch)
      }
      node.end = true
    } else {
      out.push(matches(root, text, 0))
    }
  }
  return out
}

