class Node:
    def __init__(self):
        self.children = {}
        self.end = False


def word_dictionary_ops(ops):
    root = Node()

    def matches(node, pattern, i):
        # Does the rest of the pattern, from index i, match a word below node?
        if i == len(pattern):
            return node.end
        ch = pattern[i]
        if ch == ".":
            return any(matches(child, pattern, i + 1) for child in node.children.values())
        child = node.children.get(ch)
        return child is not None and matches(child, pattern, i + 1)

    out = []
    for op, text in ops:
        if op == "add":
            node = root
            for ch in text:
                node = node.children.setdefault(ch, Node())
            node.end = True
        else:
            out.append(matches(root, text, 0))
    return out

