function findWords(board, words) {
  const root = {}
  for (const word of words) {
    let node = root
    for (const ch of word) {
      if (!node[ch]) node[ch] = {}
      node = node[ch]
    }
    node.$ = word // a word ends here
  }
  const rows = board.length
  const cols = board[0].length
  const found = []
  const dfs = (r, c, parent) => {
    const ch = board[r][c]
    const node = parent[ch]
    if (!node) return
    if (node.$ !== undefined) {
      found.push(node.$)
      delete node.$ // report each word once
    }
    board[r][c] = '#' // in use on this path
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr
      const nc = c + dc
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] !== '#') dfs(nr, nc, node)
    }
    board[r][c] = ch
    if (Object.keys(node).length === 0) delete parent[ch] // nothing left to find below
  }
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) dfs(r, c, root)
  }
  return found
}

