def find_redundant_connection(edges):
    parent = list(range(len(edges) + 1))
    rank = [0] * (len(edges) + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return [a, b]                   # already connected: this cable closes the loop
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra                     # attach the shorter tree under the taller one
        if rank[ra] == rank[rb]:
            rank[ra] += 1
    return []

