    parent = list(range(26))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def idx(ch):
        return ord(ch) - ord("a")

    for eq in equations:                # pass 1: merge everything that must be equal
        if eq[1] == "=":
            parent[find(idx(eq[0]))] = find(idx(eq[3]))
    for eq in equations:                # pass 2: no "!=" may join one group
        if eq[1] == "!" and find(idx(eq[0])) == find(idx(eq[3])):
